package hu.bankmonitor.payments;

import jakarta.servlet.DispatcherType;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Configuration;
import org.springframework.http.HttpHeaders;
import org.springframework.http.HttpMethod;
import org.springframework.security.config.Customizer;
import org.springframework.security.config.annotation.web.builders.HttpSecurity;
import org.springframework.security.config.annotation.web.configuration.EnableWebSecurity;
import org.springframework.security.config.annotation.web.configurers.AbstractHttpConfigurer;
import org.springframework.security.config.http.SessionCreationPolicy;
import org.springframework.security.web.SecurityFilterChain;
import org.springframework.web.cors.CorsConfiguration;
import org.springframework.web.cors.CorsConfigurationSource;
import org.springframework.web.cors.UrlBasedCorsConfigurationSource;

import java.util.List;

/**
 * The one filter chain: stateless, cross-origin to the frontend, and open to callers.
 *
 * <p>This application has no authentication and no principal — design decision 2 declined
 * to model a user, and nothing downstream learns who called. That deferral is why every
 * setting here is spelled out instead of assumed: a chain that says {@code permitAll} in
 * so many words is a decision, whereas an absent dependency is an omission, and the two
 * are indistinguishable in a running application. The one real authorization rule arrives
 * with the endpoint it protects (design decision 10).
 *
 * <p>It sits in the root package beside the application class because it belongs to no
 * slice; the domain packages own their own behaviour, not the chain in front of it.
 */
@Configuration
@EnableWebSecurity
class SecurityConfiguration {

	private static final String PUBLIC_API = "/api/**";

	private static final String HEALTH_CHECK = "/actuator/health";

	private static final String[] API_DOCUMENTATION = {
			"/v3/api-docs/**", "/swagger-ui/**", "/swagger-ui.html"};

	/** Named in {@code CONTEXT.md}; ticket 16 gives it a constant in the slice that reads it. */
	private static final String IDEMPOTENCY_KEY_HEADER = "X-Idempotency-Key";

	@Bean
	SecurityFilterChain securityFilterChain(HttpSecurity http) throws Exception {
		return http
				// Nothing to forge with: the API is stateless JSON, carries no cookie and no
				// Authorization header, and the CORS policy below sends no credentials. CSRF
				// tokens defend ambient authority, and there is none here to borrow.
				.csrf(AbstractHttpConfigurer::disable)
				// Reads the CorsConfigurationSource bean below. Security runs ahead of MVC and
				// answers the preflight itself, so a @CrossOrigin annotation would never be
				// reached — the symptom is a browser-only failure that curl cannot reproduce.
				.cors(Customizer.withDefaults())
				.sessionManagement(session -> session.sessionCreationPolicy(SessionCreationPolicy.STATELESS))
				.authorizeHttpRequests(request -> request
						// The authorization filter runs on the ERROR dispatch too. Without this,
						// deny-by-default turns every 404 and 405 into an empty 403 and swallows
						// the problem documents of design decision 18. ASYNC is the continuation
						// of a request already authorized on its way in — the SSE stream of
						// design decision 17 is served on one.
						.dispatcherTypeMatchers(DispatcherType.ERROR, DispatcherType.ASYNC).permitAll()
						.requestMatchers(PUBLIC_API).permitAll()
						.requestMatchers(HEALTH_CHECK).permitAll()
						.requestMatchers(API_DOCUMENTATION).permitAll()
						// Deny-by-default, so reaching a new prefix takes an entry above rather
						// than nothing at all. `/internal/**` becomes that entry in ticket 21.
						.anyRequest().denyAll())
				.build();
	}

	/**
	 * The browser-facing half of the policy, mapped onto {@link #PUBLIC_API} alone: the
	 * mock FX provider stands in for a third party reached server-to-server, and putting it
	 * under our CORS policy would undo the isolation it exists for (design decision 28).
	 *
	 * @param allowedOrigins the origins allowed to call this API from a browser, defaulting
	 *                       to the Vite dev server that design decision 20 runs as a
	 *                       separate process
	 */
	@Bean
	CorsConfigurationSource corsConfigurationSource(
			@Value("${payments.cors.allowed-origins}") List<String> allowedOrigins) {
		CorsConfiguration policy = new CorsConfiguration();
		policy.setAllowedOrigins(allowedOrigins);
		policy.setAllowedMethods(List.of(HttpMethod.GET.name(), HttpMethod.POST.name()));
		policy.setAllowedHeaders(List.of(HttpHeaders.CONTENT_TYPE, IDEMPOTENCY_KEY_HEADER));
		// Only the safelisted response headers reach cross-origin JavaScript. Retry-After
		// carries the retry policy of design decision 18, and the frontend reads it as
		// absent unless it is named here.
		policy.setExposedHeaders(List.of(HttpHeaders.RETRY_AFTER));
		// What keeps CSRF-off safe, and the reason the origin list is explicit rather than a
		// wildcard: no cookie or credential rides along on a cross-origin call.
		policy.setAllowCredentials(false);

		UrlBasedCorsConfigurationSource source = new UrlBasedCorsConfigurationSource();
		source.registerCorsConfiguration(PUBLIC_API, policy);
		return source;
	}
}

