package hu.bankmonitor.payments;

import org.springframework.boot.SpringApplication;
import org.springframework.boot.autoconfigure.SpringBootApplication;
import org.springframework.boot.security.autoconfigure.UserDetailsServiceAutoConfiguration;

// The excluded auto-configuration would create an in-memory user with a random password
// and log it at every startup. Nothing authenticates against it — see SecurityConfiguration
// — and an account no one can use reads as configuration left unfinished.
@SpringBootApplication(exclude = UserDetailsServiceAutoConfiguration.class)
public class GlobalPaymentServiceApplication {

	public static void main(String[] args) {
		SpringApplication.run(GlobalPaymentServiceApplication.class, args);
	}

}

